slug: shared-counter-increment-race
stack: dotnet
topic: concurrency
level: junior
type: find-bug
grading: auto
tags: [race-condition, interlocked, threads, atomicity]
code:
  language: csharp
  harness: statements
  source: |
    int counter = 0;
    Thread[] workers = new Thread[4];

    for (int i = 0; i < workers.Length; i++)
    {
        workers[i] = new Thread(() =>
        {
            for (int j = 0; j < 1_000_000; j++)
            {
                counter++;
            }
        });
        workers[i].Start();
    }

    foreach (Thread worker in workers)
    {
        worker.Join();
    }

    Console.WriteLine(counter);
bugLineSets: [[10]]
fixedSource: |
  int counter = 0;
  Thread[] workers = new Thread[4];

  for (int i = 0; i < workers.Length; i++)
  {
      workers[i] = new Thread(() =>
      {
          for (int j = 0; j < 1_000_000; j++)
          {
              Interlocked.Increment(ref counter);
          }
      });
      workers[i].Start();
  }

  foreach (Thread worker in workers)
  {
      worker.Join();
  }

  Console.WriteLine(counter);
fixedExpect: { kind: output, value: "4000000" }
